package top.rongshangs.lumacurve.refactor;
import org.json.*;
/** Coordinate metadata and explicit v3 node control; legacy v1 gestures remain ignored. */
final class ControlCenterEngine {
 static final String REQUEST="hyperlux_control_center_request_v1",UI="hyperlux_control_center_ui_v1",TABLES="hyperlux_control_center_tables_v2";
 static final java.util.concurrent.ThreadPoolExecutor IO=new java.util.concurrent.ThreadPoolExecutor(0,1,10,java.util.concurrent.TimeUnit.SECONDS,new java.util.concurrent.ArrayBlockingQueue<>(2),r->{Thread t=new Thread(r,"HyperLux-slider-calibration");t.setDaemon(true);return t;},new java.util.concurrent.ThreadPoolExecutor.AbortPolicy());
 volatile JSONObject screenNitCalibration;volatile String screenNitPhysical="";Object screenNitSource;
 final HookRuntime s;final ControlCenterNodes nodes;volatile boolean registered,closed,unsupported;boolean queued;int maximum,mode,partitionMaximum;String path="";volatile String error="";long accepted,rejected;volatile JSONObject calibration,partition;volatile String partitionError="";Object sourceConfig;boolean enabled;String revision="";int user=-1;
 ControlCenterEngine(HookRuntime s){this.s=s;nodes=new ControlCenterNodes(this);}
 void start(){registered=s.brightnessControl.mainDisplay();if(registered){nodes.start();calibrate();}}
 synchronized void calibrate(){if(closed||!registered||queued)return;queued=true;try{IO.execute(()->{try{if(closed)return;Object current=ControlCenterCalibration.configuration(s.owner);
 if(screenNitSource!=current){screenNitCalibration=null;screenNitPhysical="";screenNitSource=current;try{String physical=nodes.physical();JSONObject n=ScreenBrightnessReading.calibration(s.owner);if(physical.equals(nodes.physical())&&ControlCenterCalibration.configuration(s.owner)==current){screenNitPhysical=physical;screenNitCalibration=n;}}catch(Exception unavailable){}}
 JSONObject sampled=sourceConfig==current?calibration:null;if(sampled==null)sampled=ControlCenterCalibration.read(s.owner);if(ControlCenterCalibration.configuration(s.owner)!=current)throw new IllegalStateException("显示配置正在变化，请重试自检");JSONObject split=null;String splitError="";try{split=ControlCenterPartition.read(s.owner,sampled);}catch(Exception|LinkageError unavailable){splitError=unavailable.toString();}synchronized(this){if(closed)return;partition=split;partitionError=splitError;sourceConfig=current;calibration=sampled;unsupported=false;error="";publishTables();}}catch(Throwable unavailable){synchronized(this){calibration=null;partition=null;sourceConfig=null;unsupported=unavailable instanceof IllegalArgumentException||unavailable instanceof NoSuchMethodException||unavailable instanceof NoSuchFieldException||unavailable instanceof ClassNotFoundException||unavailable instanceof LinkageError;error=unavailable.toString();if(!closed)s.stateWriter.submit("slider_tables",java.util.Collections.singletonMap(TABLES,null));}}finally{synchronized(this){queued=false;}}});}catch(java.util.concurrent.RejectedExecutionException unavailable){queued=false;error=unavailable.toString();}}
 boolean waiting(){return !unsupported;}
 boolean supported(){calibrate();return registered&&calibration!=null;}
 synchronized void configure(JSONObject config){if(!config.optBoolean("enabled")||(config.optInt("control_center_node_mode")<3||mode!=config.optInt("control_center_node_mode"))||mode==4&&partitionMaximum!=config.optInt("control_center_partition_maximum",0)||maximum!=config.optInt("control_center_node_maximum",0)||!path.equals(config.optString("control_center_node_path",""))||user!=config.optInt("user_serial",-1))nodes.deactivate();mode=config.optInt("control_center_node_mode");partitionMaximum=config.optInt("control_center_partition_maximum",0);maximum=config.optInt("control_center_node_maximum",0);path=config.optString("control_center_node_path","");enabled=config.optBoolean("enabled")&&config.optInt("control_center_node_mode")>0;revision=config.optString("revision");user=config.optInt("user_serial",-1);publishTables();}
 synchronized void deactivate(){nodes.deactivate(true);enabled=false;revision="";user=-1;publishTables();}
 synchronized void publishTables(){try{String raw=calibration==null?null:new JSONObject().put("build",AppBuild.BUILD).put("pid",android.os.Process.myPid()).put("process_start",HookRuntime.processStart()).put("boot_count",android.provider.Settings.Global.getString(s.context.getContentResolver(),"boot_count")).put("enabled",enabled).put("revision",revision).put("user_serial",user).put("calibration",calibration).put("partition",partition).put("partition_maximum",partitionMaximum).put("maximum",maximum).put("physical",nodes.physical()).put("raw_control",nodes.status()).toString();if(!closed)s.stateWriter.submit("slider_tables",java.util.Collections.singletonMap(TABLES,raw));}catch(Exception failure){error=failure.toString();if(!closed)s.stateWriter.submit("slider_tables",java.util.Collections.singletonMap(TABLES,null));}}
 // Already queued v1 gestures must never switch mode or arm a raw lease.
 void request(){}
 JSONObject status()throws JSONException{if(s.brightnessControl.options.nodeSliderMode>=3)publishTables();JSONObject ready=calibration;return new JSONObject().put("enabled",enabled).put("revision",revision).put("user_serial",user).put("mode",s.brightnessControl.options.nodeSliderMode).put("maximum",maximum).put("registered",registered).put("coordinate_ready",calibration!=null).put("kind","coordinate_v2").put("calibration_profile",ready==null?"":ready.optString("profile","coordinate_v2")).put("compatibility_state",unsupported?"unsupported":ready==null?"pending":"available").put("oem_v1_ready",ready!=null&&ready.has("oem_v1")).put("oem_v1_detail",ready==null?"":ready.optString("oem_v1_detail")).put("error",error).put("partition",partition).put("partition_error",partitionError).put("partition_ready",partition!=null&&nodes.supported()).put("raw_ready",nodes.supported()).put("raw_control",nodes.status()).put("accepted",accepted).put("rejected",rejected);}
 synchronized void close(){deactivate();nodes.close();closed=true;registered=false;}
}
